import {studioAR,studioMaster} from './music-industry.js';export function mountMusicIndustry({root,getProject,render,busy}){if(root.querySelector('[data-music-industry]'))return;const panel=document.createElement('section');panel.className='mastering-tools';panel.dataset.musicIndustry='';panel.innerHTML='<details style="width:100%"><summary>WAR A&amp;R / WAR MASTER LAB</summary><p>Analyse non destructive de la session courante. Mesures indicatives, pas de certification normative.</p><button type="button" class="outline-btn" data-ar>Analyser la composition</button> <select aria-label="Profil de livraison"><option value="streaming">Streaming (indicatif)</option><option value="broadcast">Broadcast (indicatif)</option><option value="premaster">Premaster</option></select> <button type="button" class="outline-btn" data-ml>Analyser le master</button><p role="status"></p><pre style="max-height:280px;overflow:auto;white-space:pre-wrap"></pre></details>';root.append(panel);const ar=panel.querySelector('[data-ar]'),ml=panel.querySelector('[data-ml]'),status=panel.querySelector('[role=status]'),out=panel.querySelector('pre');const show=r=>{out.textContent=JSON.stringify(r,(k,v)=>typeof v==='number'&&!Number.isFinite(v)?null:v,2);status.textContent='Analyse terminée — résultats à interpréter à l’écoute';};const fail=e=>{out.textContent='';status.textContent=e.message};ar.onclick=()=>{try{if(busy())throw Error('Termine la prise en cours');show(studioAR(structuredClone(getProject())))}catch(e){fail(e)}};ml.onclick=async()=>{ar.disabled=ml.disabled=true;out.textContent='';try{if(busy())throw Error('Termine la prise en cours');status.textContent='Rendu hors ligne en cours…';const r=await studioMaster(structuredClone(getProject()),render,panel.querySelector('select').value);show({...r,spectrum:r.spectrum.filter((_,i)=>i%8===0),stereo:{...r.stereo,envelope:undefined}})}catch(e){fail(e)}finally{ar.disabled=ml.disabled=false}};}